import*as SDK from"../../../core/sdk/sdk.js";const SCREENSHOT_WIDTH=160,SCREENSHOT_MAX_HEIGHT=240;async function captureScreenshot(){const e=SDK.TargetManager.TargetManager.instance().primaryPageTarget();if(!e)throw new Error("Could not find main target");const{data:t}=await e.pageAgent().invoke_captureScreenshot({});return"data:image/png;base64,"+t}export async function resizeScreenshot(e){const t=new Image,a=new Promise((e=>{t.onload=e}));t.src=e,await a;const n=document.createElement("canvas"),r=n.getContext("2d");if(!r)throw new Error("Could not create context.");const o=t.width/t.height;n.width=SCREENSHOT_WIDTH,n.height=Math.min(SCREENSHOT_MAX_HEIGHT,SCREENSHOT_WIDTH/o);const c=await createImageBitmap(t,{resizeWidth:SCREENSHOT_WIDTH,resizeQuality:"high"});return r.drawImage(c,0,0),n.toDataURL("image/png")}export async function takeScreenshot(){const e=await captureScreenshot();return await resizeScreenshot(e)}